import {
    createContext,
    useCallback,
    useContext,
    useEffect,
    useMemo,
    useState,
    type ReactNode,
} from 'react';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useAppSelector } from '@/core/global-store';
import { unwrapSanctumMeResponse } from '@/features/auth/guard/utils';

export const SELF_SERVICE_SELECTED_EMPLOYEE_KEY = 'self-services-selected-employee-id';

export type SelfServiceEmployeeOption = { id: number; name: string };

type SelfServiceEmployeeContextValue = {
    effectiveEmployeeId: number | null;
    selectedEmployeeId: number | null;
    setSelectedEmployeeId: (id: number | null) => void;
    isPrivileged: boolean;
    needsEmployeeSelection: boolean;
    ready: boolean;
    employeeOptions: SelfServiceEmployeeOption[];
};

const SelfServiceEmployeeContext = createContext<SelfServiceEmployeeContextValue | null>(null);

function computePrivileged(userRole: string | undefined, me: Record<string, unknown> | null): boolean {
    if (userRole === 'super_admin' || userRole === 'admin') {
        return true;
    }
    const roles = me?.roles as Array<{ name?: string }> | undefined;
    if (Array.isArray(roles)) {
        return roles.some((x) => x?.name === 'super admin' || x?.name === 'admin');
    }
    return false;
}

export function SelfServiceEmployeeProvider({ children }: { children: ReactNode }) {
    const user = useAppSelector((s) => s.auth.user);
    const me = useAppSelector((s) => s.auth.me);

    const isPrivileged = useMemo(
        () => computePrivileged(user?.role, me as Record<string, unknown> | null),
        [user?.role, me],
    );

    const meEmployeeId = useMemo(() => {
        const raw = (me as Record<string, unknown> | null)?.employee_id;
        return typeof raw === 'number' ? raw : typeof raw === 'string' ? parseInt(raw, 10) : null;
    }, [me]);

    const [selectedEmployeeId, setSelectedEmployeeIdState] = useState<number | null>(null);
    const [employeeOptions, setEmployeeOptions] = useState<SelfServiceEmployeeOption[]>([]);
    const [optionsLoaded, setOptionsLoaded] = useState(false);

    const setSelectedEmployeeId = useCallback(
        (id: number | null) => {
            setSelectedEmployeeIdState(id);
            if (isPrivileged) {
                if (id != null) {
                    sessionStorage.setItem(SELF_SERVICE_SELECTED_EMPLOYEE_KEY, String(id));
                } else {
                    sessionStorage.removeItem(SELF_SERVICE_SELECTED_EMPLOYEE_KEY);
                }
            }
        },
        [isPrivileged],
    );

    useEffect(() => {
        if (!isPrivileged) {
            setSelectedEmployeeIdState(Number.isFinite(meEmployeeId as number) ? (meEmployeeId as number) : null);
            setOptionsLoaded(true);
            return;
        }

        const stored = sessionStorage.getItem(SELF_SERVICE_SELECTED_EMPLOYEE_KEY);
        const storedId = stored ? parseInt(stored, 10) : NaN;
        if (Number.isFinite(storedId)) {
            setSelectedEmployeeIdState(storedId);
        }

        let cancelled = false;
        setOptionsLoaded(false);
        (async () => {
            try {
                const res = await apiGet({ endpoint: endpoints.employee.simpleList });
                const rows = res.data?.data;
                const list = Array.isArray(rows)
                    ? rows.map((e: { id: number; name: string }) => ({
                          id: e.id,
                          name: e.name ?? `موظف #${e.id}`,
                      }))
                    : [];
                if (!cancelled) {
                    setEmployeeOptions(list);
                    setOptionsLoaded(true);
                }
            } catch {
                if (!cancelled) {
                    setEmployeeOptions([]);
                    setOptionsLoaded(true);
                }
            }
        })();
        return () => {
            cancelled = true;
        };
    }, [isPrivileged, meEmployeeId]);

    const refreshMeEmployeeId = useCallback(async () => {
        try {
            const res = await apiGet({ endpoint: endpoints.auth.me });
            const payload = unwrapSanctumMeResponse(res.data);
            const raw = payload?.employee_id;
            const id = typeof raw === 'number' ? raw : typeof raw === 'string' ? parseInt(raw, 10) : null;
            if (!isPrivileged && Number.isFinite(id as number)) {
                setSelectedEmployeeIdState(id as number);
            }
        } catch {
            /* ignore */
        }
    }, [isPrivileged]);

    useEffect(() => {
        if (!isPrivileged && meEmployeeId == null && user?.email) {
            void refreshMeEmployeeId();
        }
    }, [isPrivileged, meEmployeeId, user?.email, refreshMeEmployeeId]);

    const effectiveEmployeeId = useMemo(() => {
        if (isPrivileged) {
            return selectedEmployeeId;
        }
        return Number.isFinite(meEmployeeId as number) ? (meEmployeeId as number) : selectedEmployeeId;
    }, [isPrivileged, meEmployeeId, selectedEmployeeId]);

    const needsEmployeeSelection = isPrivileged && selectedEmployeeId === null;

    const value = useMemo(
        () => ({
            effectiveEmployeeId,
            selectedEmployeeId,
            setSelectedEmployeeId,
            isPrivileged,
            needsEmployeeSelection,
            ready: optionsLoaded,
            employeeOptions,
        }),
        [
            effectiveEmployeeId,
            selectedEmployeeId,
            setSelectedEmployeeId,
            isPrivileged,
            needsEmployeeSelection,
            optionsLoaded,
            employeeOptions,
        ],
    );

    return (
        <SelfServiceEmployeeContext.Provider value={value}>{children}</SelfServiceEmployeeContext.Provider>
    );
}

/** When another page is not wrapped by the provider, read admin selection (if any). */
export function getStoredSelfServiceEmployeeId(): number | null {
    const raw = sessionStorage.getItem(SELF_SERVICE_SELECTED_EMPLOYEE_KEY);
    const id = raw ? parseInt(raw, 10) : NaN;
    return Number.isFinite(id) ? id : null;
}

export function useSelfServiceEmployee(): SelfServiceEmployeeContextValue {
    const ctx = useContext(SelfServiceEmployeeContext);
    if (!ctx) {
        throw new Error('useSelfServiceEmployee must be used within SelfServiceEmployeeProvider');
    }
    return ctx;
}
